#!/usr/bin/env bash
#
# Stage C host install and acceptance wizard (docs/CODER_RUNTIME.md §4 steps 3-4).
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — Stage C host install. Run ON company-os-host as the founder:
#
#   ssh -t company-os-host bash /opt/company-os/scripts/stage-c-host-wizard.sh prep
#   ssh -t company-os-host bash /opt/company-os/scripts/stage-c-host-wizard.sh accept
#
# Every host mutation is shown as the exact command and needs a y. Nothing here sets
# ENABLE_AUTONOMOUS_CODE_WRITE, merges, or touches production services. Only the founder
# records the attestation; this wizard is the founder's hands, not an agent's.
# ──────────────────────────────────────────────────────────────────────────

MODE="${1:-}"
case "$MODE" in prep) TOTAL_STAGES=9 ;; accept) TOTAL_STAGES=7 ;;
  *) echo "usage: stage-c-host-wizard.sh prep|accept" >&2; exit 2 ;; esac

ENV_FILE=/opt/company-os/.env
APP=/opt/company-os
CODER_TAG=company-os-coder:stage-c
JOBS=/srv/company-coder/jobs
CFG=/etc/company-coder
LOG="$HOME/stage-c-acceptance-$(date -u +%Y%m%dT%H%M%SZ).log"
declare -A OK   # acceptance booleans, true only when this run proved them

ev()  { printf '%s %s\n' "$(date -u +%FT%TZ)" "$*" >> "$LOG"; }
# do_cmd "why" cmd... — show the exact command, require y, run it, log the exit code.
do_cmd() {
  local why="$1"; shift
  say "$why"; note "\$ $*"
  confirm "Run it?" || { warn "skipped"; ev "SKIPPED: $*"; return 1; }
  local rc=0; "$@" || rc=$?
  ev "exit=$rc: $*"; return $rc
}
tag()  { docker inspect company-worker --format '{{.Config.Image}}' | sed 's/.*://'; }
sha_of() { docker exec "$1" printenv COMPANY_OS_GIT_SHA; }
# Coolify's nightly cleanup `docker rmi`s every tagged image no container uses: its coolify.managed label check is
# a broken Go template (beta.469), so the label protects nothing. A never-started container holding the image makes
# that rmi fail. Its own label must not be coolify.managed=true (inherited from the coder image), or Coolify's
# container prune removes the anchor first.
anchor() {
  docker rm -f "$1" >/dev/null 2>&1 || true
  docker create --name "$1" --label coolify.managed=false --network none --pull=never "$2" true >/dev/null \
    && ev "anchor $1 -> $2"
}

[[ -t 0 ]] || { echo "needs an interactive terminal: run it in your own terminal app as  ssh -t company-os-host bash <this script> $MODE  (not from a tool that has no TTY)" >&2; exit 1; }
sudo -n true 2>/dev/null || sudo -v   # passwordless sudo needs no prompt; otherwise ask once up front
# This host's user is not in the docker group, but sudo is passwordless: run every docker call through sudo.
docker() { command sudo docker "$@"; }
sudo docker ps >/dev/null 2>&1 || { echo "cannot run docker even via sudo" >&2; exit 1; }
cd "$APP"
banner "Stage C host ($MODE)"
note "evidence log: $LOG (non-secret; commit it to Git as the acceptance record)"

# ═══════════════════════════════ PREP (before merging #127) ═══════════════════════════════
if [[ "$MODE" == prep ]]; then

stage "Survey — read only"
say "Nothing changes in this stage."
say "deployed API SHA : $(sha_of company-api)"
say "deployed worker  : $(sha_of company-worker)"
say "flag             : ENABLE_AUTONOMOUS_CODE_WRITE=$(docker exec company-worker printenv ENABLE_AUTONOMOUS_CODE_WRITE)  (must stay false)"
say "launcher timer   : $(systemctl is-active company-coder-launch.timer || true)"
say "disk free        : $(df -h / | awk 'NR==2{print $4" free ("$5" used)"}')"
note "Building the coder image needs ~1 GB; stop if disk is above 85%."
ev "survey api=$(sha_of company-api) worker=$(sha_of company-worker)"
pause "Looks right? Enter to continue"

stage "Build the coder image (no secrets in it)"
say "Builds the 'coder' target: pinned Claude CLI only, no Codex CLI, app code or credentials."
say "Risk: ~1 GB disk, a few minutes of host CPU. Rollback: docker rmi $CODER_TAG"
do_cmd "Build from main's Dockerfile on the host." docker build --target coder -t "$CODER_TAG" "$APP" || true
docker image inspect "$CODER_TAG" >/dev/null 2>&1 && { OK[image_build]=true; ev "coder image $(docker image inspect "$CODER_TAG" --format '{{.Id}}')"; anchor company-coder-anchor "$CODER_TAG"; }
pause

stage "Start the coder egress proxy (allowlist: api.anthropic.com, chatgpt.com, auth.openai.com)"
say "Starts ONLY company-egress and creates the internal network company-coder-net."
say "Risk: one 128 MB container; touches no running service (--no-deps). Rollback:"
note "docker compose --profile stage-c rm -sf company-egress"
T=$(tag)
do_cmd "Start it with the exact tag the worker runs." sudo env COMPANY_OS_IMAGE_TAG="$T" COMPANY_OS_GIT_SHA="$T" \
  docker compose --profile stage-c up -d --no-deps --no-build company-egress || true
say "running: $(docker inspect -f '{{.State.Running}}' company-egress 2>/dev/null || echo no)   internal network: $(docker network inspect -f '{{.Internal}}' company-coder-net 2>/dev/null || echo no)"
pause

stage "Jobs directory and repository mirror (owned by uid 10001)"
say "The worker's only shared path with the launcher. 0755, never group/other writable."
say "Rollback: sudo rmdir /srv/company-coder/jobs/.control/sez-company.git; the directories are empty."
do_cmd "Create and own them." sudo install -d -o 10001 -g 10001 -m 0755 "$JOBS" "$JOBS/.control" || true
do_cmd "Initialise the empty bare mirror as the worker uid (the worker fetches main into it)." \
  sudo setpriv --reuid=10001 --regid=10001 --clear-groups git init -q --bare --initial-branch=main "$JOBS/.control/sez-company.git" || true
ls -ld "$JOBS" "$JOBS/.control/sez-company.git" 2>&1 | sed 's/^/  /'
pause

stage "Claude Code subscription token (separate from ChatGPT reviewer)"
say "The coder uses a Claude Code setup-token; this is separate from the Codex reviewer login and is not an API key."
say "Anthropic currently documents Claude Code for individual Pro/Max plans; Team-plan OAuth is not Claude Code entitlement."
say "A Team/account policy denial is not token expiry. Use an already-authorized Claude Code account; never switch to metered API billing."
say "Normal interactive Claude login stores CLI credentials; setup-token is the headless token copied to this root-only file."
step "On YOUR LAPTOP (not here), run:  claude setup-token"
step "Complete the browser login, then copy the token it prints (sk-ant-oat…)."
open_url "https://claude.ai/settings"
ask_secret CLAUDE_CODE_OAUTH_TOKEN_IN "Paste the token (hidden):"
[[ -n "$CLAUDE_CODE_OAUTH_TOKEN_IN" ]] || { warn "empty; skipping"; }
if [[ -n "$CLAUDE_CODE_OAUTH_TOKEN_IN" ]] && confirm "Write it to $CFG/claude.env (root, 0600, one line)?"; then
  sudo install -d -m 0700 -o root -g root "$CFG"
  sudo install -m 0600 -o root -g root /dev/null "$CFG/claude.env"
  printf 'CLAUDE_CODE_OAUTH_TOKEN=%s\n' "$CLAUDE_CODE_OAUTH_TOKEN_IN" | sudo tee "$CFG/claude.env" >/dev/null
  ev "claude.env written (value not logged)"
  say "stored: $(sudo stat -c '%U %a %s bytes' "$CFG/claude.env")"
fi
unset CLAUDE_CODE_OAUTH_TOKEN_IN
pause

stage "Codex independent reviewer login (company-worker-codex)"
say "Codex uses your personal ChatGPT subscription login; it is independent from Claude OAuth and is reviewer-only."
say "The reviewer runs in company-reasoner and persists credentials in company-worker-codex. No coder volume is created or used."
say "The device-code flow may be disabled by the ChatGPT account/server policy. API-key login is forbidden here."
CODEX_REVIEWER_VOLUME=$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/home/worker/.codex"}}{{.Name}}{{end}}{{end}}' company-reasoner 2>/dev/null || true)
if [[ "$CODEX_REVIEWER_VOLUME" != company-worker-codex ]]; then
  warn "company-reasoner does not mount company-worker-codex at /home/worker/.codex; login stopped without creating or changing a volume"
  ev "Codex reviewer login skipped: expected reviewer volume not mounted"
elif ! docker exec company-reasoner codex login --help 2>&1 | grep -q -- '--device-auth'; then
  warn "the installed Codex CLI does not advertise --device-auth; login stopped"
  ev "Codex reviewer login skipped: device auth flag unavailable"
elif confirm "Start ChatGPT device login in company-reasoner? The one-time code is shown only in this terminal and is never written to the evidence log."; then
  if docker exec -it company-reasoner codex login --device-auth; then
    say "Codex login command completed in the persistent reviewer volume. Live model access is still unverified."
    ev "Codex reviewer device login completed (no auth output logged)"
  else
    rc=$?
    warn "Codex device login failed (exit $rc). If it says device code login is not enabled, this is an account/server policy restriction, not Claude token expiry. Use ChatGPT browser OAuth only in an approved interactive session with secure callback access, or ask the account administrator to enable device login. Do not use an API key."
    ev "Codex reviewer device login failed rc=$rc (provider output not logged)"
  fi
else
  ev "Codex reviewer device login declined"
fi
pause

stage "Scoped GitHub token for the worker (never shown, never in prompts)"
open_url "https://github.com/settings/personal-access-tokens/new"
step "Resource owner: you. Repository access: ONLY 'sez-company'. Expiry: 30 days."
step "Repository permissions: Contents RW, Pull requests RW, Commit statuses READ, Actions READ, Metadata READ."
step "NO Workflows, NO Administration, nothing else. Generate and copy the token."
ask_secret COMPANY_STAGE_C_GITHUB_TOKEN "Paste the token (hidden):"
if [[ -n "$COMPANY_STAGE_C_GITHUB_TOKEN" ]]; then
  code=$(printf 'header = "Authorization: Bearer %s"\n' "$COMPANY_STAGE_C_GITHUB_TOKEN" \
         | curl -sS -K - -o /tmp/.repo.json -w '%{http_code}' https://api.github.com/repos/seerxo/os || true)
  say "GitHub answered $code for the repository; permissions: $(python3 -c 'import json;print(json.load(open("/tmp/.repo.json")).get("permissions"))' 2>/dev/null || echo unknown)"
  rm -f /tmp/.repo.json
  if [[ "$code" == 200 ]] && confirm "Write COMPANY_STAGE_C_GITHUB_TOKEN to $ENV_FILE? (picked up when the worker is next recreated, i.e. by the #127 deploy)"; then
    write_env COMPANY_STAGE_C_GITHUB_TOKEN "$COMPANY_STAGE_C_GITHUB_TOKEN"
    ev "github token written to .env (value not logged)"
  fi
fi
pause

stage "Give the worker the GitHub token (restarts company-worker only)"
say "The worker reads GH_TOKEN at start. This recreates ONLY company-worker, on the image it already runs"
say "(--no-deps --no-build, same SHA tag, same .env), exactly as the deploy script does."
say "Risk: a worker tick in flight is interrupted; recover_stale requeues it. API, DB, reasoner untouched."
say "Rollback: remove COMPANY_STAGE_C_GITHUB_TOKEN from $ENV_FILE and run the same command again."
say "open tasks IN_PROGRESS: $(docker exec company-postgres psql -U "${POSTGRES_USER:-company}" -d "${POSTGRES_DB:-company}" -Atc "select count(*) from tasks where status='IN_PROGRESS'" 2>/dev/null || echo unknown)"
T=$(tag)
if do_cmd "Recreate the worker with the token." sudo env COMPANY_OS_IMAGE_TAG="$T" COMPANY_OS_GIT_SHA="$T" \
     docker compose up -d --no-deps --no-build company-worker; then
  sleep 8
  say "worker SHA : $(sha_of company-worker)  (must still be $T)"
  docker exec company-worker sh -c 'test -n "$GH_TOKEN"' && say "GH_TOKEN present in worker (value never shown)" || warn "GH_TOKEN still absent"
  ev "worker recreated sha=$(sha_of company-worker)"
fi
pause

stage "Prep done — what comes next"
say "Run 'accept' whenever the deployed SHA is the one you want to accept:"
say "  bash /opt/company-os/scripts/stage-c-host-wizard.sh accept"
note "The attestation is bound to the deployed SHA, so any later deploy needs a new 'accept'."
say "ENABLE_AUTONOMOUS_CODE_WRITE is still false. It is a separate, later approval."
pause "Enter to finish"

fi
# ═══════════════════════════════ ACCEPT (after the #127 deploy) ═══════════════════════════
if [[ "$MODE" == accept ]]; then

stage "Confirm the deploy carried everything"
API=$(sha_of company-api); WRK=$(sha_of company-worker)
say "API    $API"; say "worker $WRK"
[[ "$API" == "$WRK" ]] || { warn "API and worker SHAs differ — stop."; exit 1; }
docker exec company-worker sh -c 'test -n "$GH_TOKEN"' && say "worker has GH_TOKEN (value never shown)" || { warn "worker has no GH_TOKEN — the deploy has not picked up .env"; exit 1; }
docker exec company-worker python -c 'import app.stage_c_preflight' && say "preflight module present" || { warn "PR #127 is not deployed"; exit 1; }
say "flag: ENABLE_AUTONOMOUS_CODE_WRITE=$(docker exec company-worker printenv ENABLE_AUTONOMOUS_CODE_WRITE)"
ev "accept for sha=$WRK"
confirm "Is $WRK the commit you expect (the merge of #127 or later)?" || exit 1

stage "Pin the images and install the launcher"
CODER_ID=$(docker image inspect "$CODER_TAG" --format '{{.Id}}')
CHECKS_ID=$(docker image inspect "company-os-worker:$WRK" --format '{{.Id}}')
say "coder  $CODER_ID"; say "checks $CHECKS_ID  (the deployed worker image: git+Node+tests, run offline)"
note "A later deploy builds a new worker image: re-run 'accept' after each deploy."
if confirm "Write $CFG/launcher.json and install + enable the systemd poll timer?"; then
  python3 - "$CODER_ID" "$CHECKS_ID" <<'PY' | sudo tee "$CFG/launcher.json" >/dev/null
import json, sys
print(json.dumps({"coder_image": sys.argv[1], "checks_images": {"sez-company": sys.argv[2]},
  "checks_commands": {"sez-company": ["python", "-m", "pytest", "-q"]},
  "network": "company-coder-net", "proxy": "http://company-egress:8888"}))
PY
  sudo chmod 0600 "$CFG/launcher.json"; sudo chown root:root "$CFG/launcher.json"
  # Keep both pinned images alive across Coolify's nightly cleanup (see anchor()).
  anchor company-coder-anchor "$CODER_ID" && anchor company-checks-anchor "$CHECKS_ID" \
    || warn "could not anchor the pinned images: Coolify's nightly cleanup may delete them"
  # An earlier version used a glob path unit; it misses job directories created after it starts.
  sudo systemctl disable --now company-coder-launch.path 2>/dev/null || true
  sudo rm -f /etc/systemd/system/company-coder-launch.path
  sudo install -m 0644 "$APP/scripts/systemd/company-coder-launch.service" "$APP/scripts/systemd/company-coder-launch.timer" /etc/systemd/system/
  sudo systemctl daemon-reload && sudo systemctl enable --now company-coder-launch.timer
  say "launcher timer: $(systemctl is-active company-coder-launch.timer)"
  note "Rollback: sudo systemctl disable --now company-coder-launch.timer; sudo rm /etc/systemd/system/company-coder-launch.*"
  ev "launcher.json + units installed"
fi
sudo python3 "$APP/scripts/stage-c-host-facts.py" | python3 -m json.tool | sed 's/^/  /'
pause

stage "Isolation proofs (no model calls)"
for pair in "coder:$CODER_ID" "checks:$CHECKS_ID"; do
  if sudo python3 "$APP/scripts/check-coder-sandbox.py" --image "${pair#*:}" >/tmp/.sbx.json 2>&1; then
    say "sandbox proof ${pair%%:*}: PASS"; ev "sandbox ${pair%%:*} pass"; OK[permissions]=${OK[permissions]:-true}
  else say "sandbox proof ${pair%%:*}: FAIL"; OK[permissions]=false; fi
done
PROXY_PROBE='
import http.client, json, socket
def tunnel(h):
    try:
        c = http.client.HTTPSConnection("company-egress", 8888, timeout=10); c.set_tunnel(h, 443); c.connect(); return True
    except Exception: return False
def direct():
    try: socket.create_connection(("1.1.1.1", 443), timeout=5); return True
    except Exception: return False
print(json.dumps({"direct": direct(), "github": tunnel("github.com"), "example": tunnel("example.com"),
  "anthropic": tunnel("api.anthropic.com"), "chatgpt": tunnel("chatgpt.com"), "openai_auth": tunnel("auth.openai.com")}))'
R=$(docker run --rm --pull=never --network company-coder-net --read-only --user 10001:10001 --cap-drop ALL "$CODER_TAG" python -c "$PROXY_PROBE" 2>/dev/null || echo '{}')
say "proxy probe: $R"; ev "proxy probe $R"
J() { python3 -c "import json,sys;print(json.loads(sys.argv[1]).get(sys.argv[2]))" "$R" "$1"; }
[[ "$(J direct)" == False ]]  && OK[direct_egress_blocked]=true
[[ "$(J github)" == False ]]  && OK[github_blocked]=true
[[ "$(J example)" == False ]] && OK[random_hosts_blocked]=true
[[ "$(J anthropic)$(J chatgpt)$(J openai_auth)" == TrueTrueTrue ]] && OK[provider_hosts]=true
[[ "$(docker network inspect -f '{{.Internal}}' company-coder-net)" == true && "$(docker inspect -f '{{.State.Running}}' company-egress)" == true ]] && OK[egress]=true
[[ -n "${OK[image_build]:-}" ]] || { docker image inspect "$CODER_TAG" >/dev/null 2>&1 && docker image inspect "company-os-worker:$WRK" >/dev/null 2>&1 && OK[image_build]=true; }
pause

stage "Real Claude edit through the launcher, and the reviewer probe"
say "One tiny Claude job (TASK-9001) in $JOBS: append one line to a scratch file, through the real launcher."
say "The result must be exactly that file, edited. Cleanup removes only the test directories."
edit_job() {  # edit_job KEY provider
  local k="$1" p="$2" d="$JOBS/$1"
  # A previous run leaves done/result.json behind; it would be read as this run's result.
  sudo setpriv --reuid=10001 --regid=10001 --clear-groups rm -rf "$d"
  sudo setpriv --reuid=10001 --regid=10001 --clear-groups mkdir -p "$d/workspace"
  printf 'hello\n' | sudo setpriv --reuid=10001 --regid=10001 --clear-groups tee "$d/workspace/hello.txt" >/dev/null
  printf "Append the single line 'stage-c-acceptance' to hello.txt. Change nothing else." | sudo setpriv --reuid=10001 --regid=10001 --clear-groups tee "$d/prompt.txt" >/dev/null
  printf '{"kind":"code","provider":"%s","timeout_s":600}' "$p" | sudo setpriv --reuid=10001 --regid=10001 --clear-groups tee "$d/request.json" >/dev/null
  for _ in $(seq 1 130); do [[ -f "$d/done/result.json" ]] && break; sleep 5; done
  [[ -f "$d/done/result.json" ]] || return 1
  grep -qx 'stage-c-acceptance' "$d/done/workspace/hello.txt" && [[ "$(wc -l < "$d/done/workspace/hello.txt")" == 2 ]] \
    && python3 -c 'import json,sys;sys.exit(0 if json.load(open(sys.argv[1])).get("exit")==0 else 1)' "$d/done/result.json"
}
if confirm "Run the Claude edit job?"; then edit_job TASK-9001 claude && { OK[claude_edit]=true; say "claude: PASS"; } || say "claude: FAIL"; ev "claude_edit=${OK[claude_edit]:-false}"; fi
# The auth file only proves local configuration. This explicit, one-provider model call proves
# the actual reviewer path; the structured result contains no provider error or credential data.
say "Codex reviewer probe: exactly one bounded model call through worker -> company-reasoner -> restricted egress."
say "It uses the existing ChatGPT subscription, creates no task or file change, and never falls back to API billing."
CODEX_REVIEWER_VOLUME=$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/home/worker/.codex"}}{{.Name}}{{end}}{{end}}' company-reasoner 2>/dev/null || true)
if [[ "$CODEX_REVIEWER_VOLUME" == company-worker-codex ]] && confirm "Run one explicit Codex reviewer model probe now (subscription usage is consumed)?"; then
  PROBE=$(docker exec company-worker python -m app.worker --probe-provider codex 2>/dev/null | tail -1 || true)
  if printf '%s' "$PROBE" | python3 -c 'import json,sys
try:
    payload=json.load(sys.stdin)
    result=payload.get("codex") if isinstance(payload,dict) else None
    result=result if isinstance(result,dict) else {}
except (ValueError, AttributeError):
    print("Codex reviewer probe: FAIL (invalid response)"); sys.exit(1)
ok=result.get("ok") is True
health=result.get("health")
if not isinstance(health,str) or health not in {"AVAILABLE", "CREDENTIALS_CONFIGURED", "AUTH_REQUIRED", "QUOTA_EXHAUSTED", "RATE_LIMITED", "BROKEN", "DISABLED", "METERED_BLOCKED"}:
    health="UNKNOWN"
verdict="PASS" if ok else "FAIL"
print("Codex reviewer live model access: "+verdict+" (health="+health+")")
sys.exit(0 if ok else 1)' ; then
    OK[codex_review_probe]=true
    ev "codex_review_probe=true (one actual Codex call; no response logged)"
  else
    say "Codex reviewer live model access: FAIL; raw provider output was suppressed."
    ev "codex_review_probe=false (one actual Codex call failed; no response logged)"
  fi
  unset PROBE
elif [[ "$CODEX_REVIEWER_VOLUME" != company-worker-codex ]]; then
  warn "expected reviewer volume is not mounted; probe was not run"
  ev "codex_review_probe=false (reviewer volume mismatch; no model call)"
else
  ev "codex_review_probe=false (founder declined; no model call)"
fi
pause

stage "Offline checks job"
say "Runs the fixed 'python -m pytest -q' in the checks image with --network=none. One test must PROVE no network."
d="$JOBS/TASK-9003"
sudo setpriv --reuid=10001 --regid=10001 --clear-groups rm -rf "$d"
sudo setpriv --reuid=10001 --regid=10001 --clear-groups mkdir -p "$d/checks"
printf 'import socket, pytest\ndef test_ok():\n    assert True\ndef test_no_network():\n    s = socket.socket(); s.settimeout(3)\n    with pytest.raises(OSError):\n        s.connect(("1.1.1.1", 443))\n' | sudo setpriv --reuid=10001 --regid=10001 --clear-groups tee "$d/checks/test_probe.py" >/dev/null
# no model, no quota: runs without a prompt, so it cannot be skipped by accident
{
  printf '{"kind":"checks","repo":"sez-company","timeout_s":300}' | sudo setpriv --reuid=10001 --regid=10001 --clear-groups tee "$d/request.json" >/dev/null
  for _ in $(seq 1 70); do [[ -f "$d/done/result.json" ]] && break; sleep 5; done
  python3 -c 'import json,sys;r=json.load(open(sys.argv[1]));print(r);sys.exit(0 if r.get("exit")==0 else 1)' "$d/done/result.json" \
    && { OK[offline_checks]=true; OK[launcher]=true; } || say "checks job FAILED"
  ev "offline_checks=${OK[offline_checks]:-false}"
}
pause

stage "Credential isolation — the exact container profiles"
say "Prints what the launcher will pass to docker; asserts only the allowed env, no socket, no extra mounts."
# root: the profile builder reads the root-only 0600 claude.env
if sudo python3 - <<'PY'
import importlib.machinery, importlib.util, sys, json
l = importlib.machinery.SourceFileLoader("l", "/opt/company-os/scripts/company-coder-launch"); s = importlib.util.spec_from_loader("l", l)
m = importlib.util.module_from_spec(s); l.exec_module(m)
cfg = {"coder_image": "sha256:" + "0"*64, "checks_images": {"sez-company": "sha256:" + "1"*64},
       "checks_commands": {"sez-company": ["python", "-m", "pytest", "-q"]}, "network": "n", "proxy": "http://p:8888"}
allowed = ("HOME=", "HTTPS_PROXY=", "HTTP_PROXY=", "NO_PROXY=", "no_proxy=", "CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=",
           "PYTHONDONTWRITEBYTECODE=", "TMPDIR=")
bad = []
from pathlib import Path
for req in ({"kind": "code", "provider": "claude", "timeout_s": 1},
            {"kind": "checks", "repo": "sez-company", "timeout_s": 1}):
    try: argv = m.docker_argv(req, cfg, Path("/x"), "n")
    except m.Refused as e: argv = []; bad.append(str(e)[:60])
    print(req["kind"], req.get("provider", ""), "|", " ".join(a for a in argv[:-0 or None] if a.startswith(("--env", "--mount", "--network"))))
    for a in argv:
        if a.startswith("--env=") and not a[6:].startswith(allowed): bad.append(a.split("=")[1])
        if "docker.sock" in a or a == "--privileged": bad.append(a)
try:
    m.docker_argv({"kind": "code", "provider": "codex", "timeout_s": 1}, cfg, Path("/x"), "n")
except m.Refused as e:
    if "Claude-only" in str(e) and "reviewer-only" in str(e):
        print("Codex code profile | refused as expected (reviewer-only)")
    else:
        bad.append("Codex refusal was unexpected: " + str(e)[:60])
else:
    bad.append("Codex code profile was unexpectedly accepted")
sys.exit(1 if bad else 0)
PY
then OK[credential_isolation]=true; say "profiles clean"; else say "profile check FAILED (a claude.env that is missing also lands here)"; fi
ev "credential_isolation=${OK[credential_isolation]:-false}"
pause

stage "Founder attestation, then preflight"
say "Results (true only if proven in this run):"
NEED=(image_build egress launcher permissions direct_egress_blocked github_blocked random_hosts_blocked provider_hosts claude_edit codex_review_probe offline_checks credential_isolation)
JSON="{"; ALL=1
for k in "${NEED[@]}"; do v=${OK[$k]:-false}; [[ "$v" == true ]] || ALL=0; JSON+="\"$k\": $v,"; say "$([[ $v == true ]] && echo '✓' || echo '✗') $k"; done
JSON="${JSON%,}}"
ev "attestation candidate sha=$WRK $JSON"
if (( ALL )) && confirm "Record stage-c-host-acceptance for $WRK as the founder? (a different deployed SHA later needs new acceptance)"; then
  printf '%s' "{\"source_sha\": \"$WRK\", \"checks\": $JSON}" | docker exec -i company-worker python -c '
import json, sys
from app.db import SessionLocal
from app import models
v = json.load(sys.stdin); v["evidence"] = "stage-c-host-wizard accept log"
with SessionLocal() as db:
    row = db.get(models.ControlState, "stage-c-host-acceptance")
    if row: row.value, row.updated_by = v, "founder"
    else: db.add(models.ControlState(key="stage-c-host-acceptance", value=v, updated_by="founder"))
    db.commit(); print("recorded")'
  ev "attestation recorded"
else warn "not recorded — fix the ✗ items and re-run 'accept'"; fi
say ""
sudo "$APP/scripts/companyctl" stage-c preflight || true
sudo setpriv --reuid=10001 --regid=10001 --clear-groups rm -rf "$JOBS/TASK-9001" "$JOBS/TASK-9002" "$JOBS/TASK-9003" 2>/dev/null || true
say "Log to commit as evidence: $LOG"
say "Next (separate founder decision): the one-attended-pilot compose override for ENABLE_AUTONOMOUS_CODE_WRITE."
pause "Enter to finish"

fi
finish
